begin;
update public.questions set subject = 'History', topic = 'Ancient', type = 'match_the_following', difficulty = 'medium', body = 'Consider the following pairs of finds at Harappan sites and what they are taken to suggest:', body_hi = 'हड़प्पा स्थलों पर मिली वस्तुओं और उनसे लगाए जाने वाले निष्कर्षों के निम्नलिखित युग्मों पर विचार कीजिए:', explanation = 'Three pairs are correct. The furrows at Kalibangan run in two directions at right angles, a pattern still used in the region to grow two crops, such as mustard and gram, in one field. Dholavira, in the dry Rann of Kachchh, had a chain of reservoirs and channels to store run-off. The workshops at Chanhudaro, with tools and beads at every stage of making, point to specialised crafts serving trade. Pair 4 is wrong: the Harappans used copper and bronze, not iron, which came into use in the subcontinent only around 1000 BCE or a little earlier. Banawali is known for a terracotta model of a plough.', explanation_hi = 'तीन युग्म सही हैं। कालीबंगा की कूँड़ें एक-दूसरे से समकोण पर दो दिशाओं में हैं, यह पद्धति आज भी उस क्षेत्र में एक खेत में दो फ़सलें, जैसे सरसों और चना, उगाने के लिए अपनाई जाती है। सूखे कच्छ के रण में स्थित धोलावीरा में बहते पानी को रोकने के लिए जलाशयों और नालियों की शृंखला थी। हर चरण के औज़ारों और मनकों वाली चन्हूदड़ो की कार्यशालाएँ व्यापार के लिए विशिष्ट शिल्पों की ओर संकेत करती हैं। युग्म 4 गलत है: हड़प्पावासी लोहे का नहीं, ताँबे और काँसे का उपयोग करते थे; उपमहाद्वीप में लोहा लगभग 1000 ई.पू. या उससे थोड़ा पहले प्रयोग में आया। बनावली हल के मिट्टी के एक नमूने के लिए जाना जाता है।', concept_group_id = 'ancient-harappan-sites-features-pairs', source_citation = 'Upinder Singh, A History of Ancient and Early Medieval India (Pearson)', question_data = '{"list_1": ["1. A ploughed field with criss-cross furrows at Kalibangan", "2. Large reservoirs at Dholavira", "3. Bead-making workshops at Chanhudaro", "4. Iron implements at Banawali"], "list_1_hi": ["1. कालीबंगा में आड़ी-तिरछी कूँड़ों वाला जुता खेत", "2. धोलावीरा के बड़े जलाशय", "3. चन्हूदड़ो की मनका बनाने की कार्यशालाएँ", "4. बनावली में लोहे के औज़ार"], "list_2": ["Two crops were grown together in the same field", "Careful harvesting of water in a dry region", "Specialised craft production", "Knowledge of iron smelting"], "list_2_hi": ["एक ही खेत में दो फ़सलें साथ उगाई जाती थीं", "सूखे क्षेत्र में जल का सावधानीपूर्वक संग्रहण", "विशिष्ट शिल्प उत्पादन", "लोहा गलाने का ज्ञान"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": true}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ancient-harappan-sites-features-pairs' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Ancient', type = 'match_the_following', difficulty = 'medium', body = 'Consider the following pairs of Vedic terms and what they tell us about Vedic society:', body_hi = 'निम्नलिखित वैदिक शब्दों और उनसे वैदिक समाज के बारे में मिलने वाली जानकारी के युग्मों पर विचार कीजिए:', explanation = 'Three pairs are correct. That war could be called ''the search for cows'' shows how far wealth and conflict turned on cattle. Women''s presence in the vidatha, one of the oldest assemblies, suggests they had some public role in the early period. The bhagadugha, among the officials named in later Vedic texts, reflects the growth of kingship and of a regular royal share. Pair 2 is wrong: in the Rig Vedic period bali was a voluntary offering to the chief, often from the spoils of war; it hardened into a compulsory tax only later, as kingdoms took shape.', explanation_hi = 'तीन युग्म सही हैं। युद्ध को ''गायों की खोज'' कहा जा सकना दिखाता है कि धन और संघर्ष कितना पशुओं पर टिके थे। सबसे पुरानी सभाओं में से एक विदथ में स्त्रियों की उपस्थिति बताती है कि प्रारंभिक काल में उनकी कुछ सार्वजनिक भूमिका थी। उत्तर वैदिक ग्रंथों में वर्णित अधिकारियों में से एक भागदुघ राजत्व और नियमित राजकीय भाग की वृद्धि को दर्शाता है। युग्म 2 गलत है: ऋग्वैदिक काल में बलि मुखिया को दी जाने वाली स्वैच्छिक भेंट थी, जो प्रायः युद्ध की लूट से आती थी; राज्यों के बनने के साथ यह बाद में ही अनिवार्य कर बनी।', concept_group_id = 'ancient-vedic-terms-pairs', source_citation = 'R.S. Sharma, India''s Ancient Past (Oxford University Press)', question_data = '{"list_1": ["1. Gavishti, ''the search for cows'', a word for war", "2. Bali, an offering to the chief", "3. Vidatha, an assembly in which women took part", "4. Bhagadugha, the collector of the king''s share"], "list_1_hi": ["1. गविष्टि, ''गायों की खोज'', युद्ध के लिए एक शब्द", "2. बलि, मुखिया को दी जाने वाली भेंट", "3. विदथ, एक सभा जिसमें स्त्रियाँ भाग लेती थीं", "4. भागदुघ, राजा का भाग वसूलने वाला"], "list_2": ["Cattle raids were a common cause of conflict", "A tax fixed and collected by royal officials from the start", "Women had some share in public life", "The growth of royal revenue in the later Vedic period"], "list_2_hi": ["पशु-हरण संघर्ष का एक आम कारण था", "शुरू से ही राजकीय अधिकारियों द्वारा तय और वसूला जाने वाला कर", "सार्वजनिक जीवन में स्त्रियों की कुछ भागीदारी थी", "उत्तर वैदिक काल में राजकीय राजस्व की वृद्धि"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": true}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ancient-vedic-terms-pairs' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Ancient', type = 'match_the_following', difficulty = 'medium', body = 'Consider the following pairs of schools of Indian philosophy and their central concerns:', body_hi = 'भारतीय दर्शन के निम्नलिखित संप्रदायों और उनकी केंद्रीय चिंताओं के युग्मों पर विचार कीजिए:', explanation = 'Only pairs 1 and 2 are correct. Nyaya, attributed to Gautama, set out the means of valid knowledge -- perception, inference, comparison and testimony -- and Vaisheshika, attributed to Kanada, explained the world through atoms and a set of categories. Pair 3 is wrong: classical Sankhya, attributed to Kapila, is a dualism of purusha (spirit) and prakriti (matter) and does not need a creator god. Pair 4 describes Yoga, systematised by Patanjali; Mimamsa, attributed to Jaimini, is concerned with interpreting the Vedic injunctions and the performance of ritual.', explanation_hi = 'केवल युग्म 1 और 2 सही हैं। गौतम को श्रेय दिए जाने वाले न्याय ने प्रामाणिक ज्ञान के साधन, यानी प्रत्यक्ष, अनुमान, उपमान और शब्द, निर्धारित किए, और कणाद को श्रेय दिए जाने वाले वैशेषिक ने संसार की व्याख्या परमाणुओं और कुछ पदार्थों के माध्यम से की। युग्म 3 गलत है: कपिल को श्रेय दिया जाने वाला शास्त्रीय सांख्य पुरुष (चेतना) और प्रकृति (जड़) का द्वैतवाद है और उसे सृष्टिकर्ता ईश्वर की आवश्यकता नहीं। युग्म 4 योग का वर्णन करता है, जिसे पतंजलि ने व्यवस्थित किया; जैमिनि को श्रेय दिया जाने वाला मीमांसा वैदिक विधियों की व्याख्या और कर्मकांड के पालन से जुड़ा है।', concept_group_id = 'ancient-darshanas-founders-pairs', source_citation = 'R.S. Sharma, India''s Ancient Past (Oxford University Press)', question_data = '{"list_1": ["1. Nyaya", "2. Vaisheshika", "3. Sankhya", "4. Mimamsa"], "list_1_hi": ["1. न्याय", "2. वैशेषिक", "3. सांख्य", "4. मीमांसा"], "list_2": ["Logic and the means of valid knowledge", "The analysis of the world into atoms and categories", "The worship of a personal creator god", "Meditation and the discipline of body and mind"], "list_2_hi": ["तर्कशास्त्र और प्रामाणिक ज्ञान के साधन", "संसार का परमाणुओं और पदार्थों में विश्लेषण", "एक साकार सृष्टिकर्ता ईश्वर की उपासना", "ध्यान और शरीर तथा मन का अनुशासन"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true, "craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": true}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ancient-darshanas-founders-pairs' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Ancient', type = 'mcq', difficulty = 'easy', body = 'The Rig Veda mentions the Indus and its tributaries again and again, but the Ganga only once or twice. This suggests that the early Vedic people:', body_hi = 'ऋग्वेद में सिंधु और उसकी सहायक नदियों का बार-बार उल्लेख है, पर गंगा का केवल एक-दो बार। इससे संकेत मिलता है कि प्रारंभिक वैदिक लोग:', explanation = 'The Rig Veda calls their land Sapta Sindhu, the land of seven rivers -- the Indus, its Punjab tributaries and the Saraswati. The rare mentions of the Ganga and the Yamuna show that the Gangetic plain lay at the edge of their world. Later Vedic texts describe the movement eastwards into the Ganga-Yamuna doab and beyond, where kingdoms such as the Kurus and Panchalas arose. Nothing in the hymns points to a sea-faring life or to the Deccan.', explanation_hi = 'ऋग्वेद उनके प्रदेश को सप्त सिंधु, यानी सात नदियों का देश, कहता है: सिंधु, पंजाब की उसकी सहायक नदियाँ और सरस्वती। गंगा और यमुना के दुर्लभ उल्लेख बताते हैं कि गंगा का मैदान उनके संसार के किनारे पर था। उत्तर वैदिक ग्रंथ पूर्व की ओर गंगा-यमुना दोआब और उससे आगे बढ़ने का वर्णन करते हैं, जहाँ कुरु और पांचाल जैसे राज्य उभरे। ऋचाओं में समुद्री जीवन या दक्कन की ओर कोई संकेत नहीं है।', concept_group_id = 'ancient-sapta-sindhu', source_citation = 'R.S. Sharma, India''s Ancient Past (Oxford University Press)', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "lived mainly in the Ganga valley but did not yet regard that river as sacred", "body_hi": "मुख्यतः गंगा घाटी में रहते थे, पर उस नदी को अभी पवित्र नहीं मानते थे", "isCorrect": false}, {"id": "b", "body": "were sea-faring people who settled along the western coast", "body_hi": "समुद्री यात्री थे जो पश्चिमी तट पर बस गए", "isCorrect": false}, {"id": "c", "body": "lived mainly in the north-west, in the land of the Indus and its tributaries", "body_hi": "मुख्यतः उत्तर-पश्चिम में, सिंधु और उसकी सहायक नदियों के प्रदेश में रहते थे", "isCorrect": true}, {"id": "d", "body": "had moved into the Deccan before they reached the Punjab", "body_hi": "पंजाब पहुँचने से पहले दक्कन में जा चुके थे", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ancient-sapta-sindhu' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Ancient', type = 'mcq', difficulty = 'easy', body = 'James Prinsep''s decipherment of the Brahmi script in 1837 was a landmark for Indian history mainly because it:', body_hi = '1837 में जेम्स प्रिंसेप द्वारा ब्राह्मी लिपि का पढ़ा जाना भारतीय इतिहास के लिए मुख्यतः इसलिए मील का पत्थर था कि इसने:', explanation = 'Prinsep, an official of the Calcutta mint and secretary of the Asiatic Society, worked out Brahmi and then Kharoshthi, so the edicts of a king who called himself ''Devanampiya Piyadasi'' could be read across the subcontinent; later finds tied that title to the name Ashoka. The Harappan script is still undeciphered, Harappa was excavated only from 1921, and the Rig Veda was handed down orally for centuries before it was written down, so no manuscript could date it.', explanation_hi = 'कलकत्ता टकसाल के अधिकारी और एशियाटिक सोसाइटी के सचिव प्रिंसेप ने ब्राह्मी और फिर खरोष्ठी को पढ़ा, जिससे स्वयं को ''देवानांपिय पियदसि'' कहने वाले राजा के अभिलेख पूरे उपमहाद्वीप में पढ़े जा सके; बाद की खोजों ने इस उपाधि को अशोक नाम से जोड़ा। हड़प्पा लिपि अब भी पढ़ी नहीं जा सकी है, हड़प्पा की खुदाई 1921 से ही हुई, और ऋग्वेद लिखे जाने से पहले सदियों तक मौखिक रूप से चला, इसलिए कोई पांडुलिपि उसकी तिथि तय नहीं कर सकती थी।', concept_group_id = 'ancient-prinsep-brahmi', source_citation = 'Upinder Singh, A History of Ancient and Early Medieval India (Pearson)', question_data = '{"craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "made the edicts of Ashoka readable and so opened up the history of the Mauryas", "body_hi": "अशोक के अभिलेखों को पढ़ने योग्य बनाया और इस तरह मौर्यों का इतिहास खोल दिया", "isCorrect": true}, {"id": "b", "body": "proved that the Harappan seals were written in an early form of the same Brahmi script", "body_hi": "सिद्ध किया कि हड़प्पा की मुहरें इसी ब्राह्मी लिपि के प्रारंभिक रूप में लिखी गई थीं", "isCorrect": false}, {"id": "c", "body": "led directly to the discovery of Harappa and Mohenjodaro", "body_hi": "सीधे हड़प्पा और मोहनजोदड़ो की खोज करवाई", "isCorrect": false}, {"id": "d", "body": "fixed the date of the Rig Veda by reading its earliest surviving manuscripts", "body_hi": "ऋग्वेद की सबसे पुरानी बची पांडुलिपियाँ पढ़कर उसकी तिथि तय की", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ancient-prinsep-brahmi' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Ancient', type = 'mcq', difficulty = 'easy', body = 'Historians value the Jataka tales, stories of the Buddha''s previous births, as a source chiefly on:', body_hi = 'इतिहासकार बुद्ध के पूर्व जन्मों की कथाओं, जातक कथाओं, को मुख्यतः किसके स्रोत के रूप में महत्व देते हैं?', explanation = 'Each Jataka teaches a virtue through a story of the Bodhisattva, often born as an animal, but the settings -- caravans of merchants, guilds of craftsmen, villages, ports and markets -- give a picture of everyday life in the early historical period. Scenes from them are carved on the railings and gateways of Bharhut and Sanchi. They are stories, not chronicles, so they cannot give the order of kings, and they belong to the Buddhist, not the Jain or Vedic, tradition.', explanation_hi = 'हर जातक बोधिसत्व की, जो प्रायः पशु रूप में जन्मे, कथा के माध्यम से कोई सद्गुण सिखाता है, पर उनकी पृष्ठभूमि, यानी व्यापारियों के कारवाँ, शिल्पियों की श्रेणियाँ, गाँव, बंदरगाह और बाज़ार, प्रारंभिक ऐतिहासिक काल के दैनिक जीवन का चित्र देती है। भरहुत और सांची की वेदिकाओं और तोरणों पर उनके दृश्य उकेरे गए हैं। वे कथाएँ हैं, इतिहास-वृत्त नहीं, इसलिए राजाओं का क्रम नहीं बता सकतीं, और वे बौद्ध परंपरा की हैं, जैन या वैदिक की नहीं।', concept_group_id = 'ancient-jataka-tales', source_citation = 'NCERT Class XII, Themes in Indian History', question_data = '{"craft": "linkage"}'::jsonb, options = '[{"id": "a", "body": "the exact order and dates of succession of the kings of Magadha", "body_hi": "मगध के राजाओं के उत्तराधिकार के सटीक क्रम और तिथियों का", "isCorrect": false}, {"id": "b", "body": "the teachings of the Jain Tirthankaras and the rules of Jain monks", "body_hi": "जैन तीर्थंकरों की शिक्षाओं और जैन भिक्षुओं के नियमों का", "isCorrect": false}, {"id": "c", "body": "the rules for performing the great Vedic sacrifices such as the ashvamedha", "body_hi": "अश्वमेध जैसे बड़े वैदिक यज्ञों को करने के नियमों का", "isCorrect": false}, {"id": "d", "body": "social and economic life in their times -- trade, crafts and guilds", "body_hi": "अपने समय के सामाजिक और आर्थिक जीवन का, जैसे व्यापार, शिल्प और श्रेणियाँ", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ancient-jataka-tales' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Ancient', type = 'mcq', difficulty = 'hard', body = 'The Junagadh rock inscription of the Shaka ruler Rudradaman I (about 150 CE) records his repair of the Sudarshana lake. Which one of the following conclusions do historians draw from it?', body_hi = 'शक शासक रुद्रदामन प्रथम का जूनागढ़ शिलालेख (लगभग 150 ई.) सुदर्शन झील की उसकी मरम्मत का वर्णन करता है। इतिहासकार इससे निम्नलिखित में से कौन-सा निष्कर्ष निकालते हैं?', explanation = 'The Junagadh inscription is the first long inscription in polished Sanskrit prose, by a Shaka ruler of the Western Kshatrapas, at a time when most royal records -- including those of the Satavahanas -- were in Prakrit. It also gives the lake''s history: it was built under Chandragupta Maurya by his governor Pushyagupta, given channels under Ashoka by Tushaspha, and restored by Rudradaman after a storm breached it; Skandagupta''s governor repaired it again three centuries later. Saurashtra was then Rudradaman''s own territory, and the Shakas ruled in western India until the Guptas displaced them.', explanation_hi = 'जूनागढ़ अभिलेख परिष्कृत संस्कृत गद्य का पहला लंबा अभिलेख है, जो पश्चिमी क्षत्रपों के एक शक शासक का है, उस समय जब सातवाहनों सहित अधिकांश राजकीय अभिलेख प्राकृत में थे। यह झील का इतिहास भी देता है: इसे चंद्रगुप्त मौर्य के समय उनके राज्यपाल पुष्यगुप्त ने बनवाया, अशोक के समय तुषास्फ ने इसमें नहरें जोड़ीं, और तूफ़ान से टूटने पर रुद्रदामन ने इसे फिर बनवाया; तीन सदी बाद स्कंदगुप्त के राज्यपाल ने इसकी फिर मरम्मत की। तब सौराष्ट्र स्वयं रुद्रदामन का क्षेत्र था, और गुप्तों द्वारा हटाए जाने तक शक पश्चिमी भारत पर शासन करते रहे।', concept_group_id = 'ancient-junagadh-rock-inscription-rudradaman', source_citation = 'Upinder Singh, A History of Ancient and Early Medieval India (Pearson)', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "The Sudarshana lake had been built by Ashoka himself, to irrigate the dry lands of Saurashtra", "body_hi": "सुदर्शन झील स्वयं अशोक ने सौराष्ट्र की सूखी भूमि की सिंचाई के लिए बनवाई थी", "isCorrect": false}, {"id": "b", "body": "A ruler of foreign origin used long, polished Sanskrit for royal records before the Guptas", "body_hi": "विदेशी मूल के एक शासक ने गुप्तों से पहले राजकीय अभिलेखों के लिए लंबी, परिष्कृत संस्कृत का उपयोग किया", "isCorrect": true}, {"id": "c", "body": "The Shakas had by then given up their rule in western India", "body_hi": "शकों ने तब तक पश्चिमी भारत में अपना शासन छोड़ दिया था", "isCorrect": false}, {"id": "d", "body": "Saurashtra had passed under the rule of the Satavahanas by the middle of the second century CE", "body_hi": "दूसरी सदी ई. के मध्य तक सौराष्ट्र सातवाहनों के शासन में आ चुका था", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ancient-junagadh-rock-inscription-rudradaman' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Ancient', type = 'mcq', difficulty = 'hard', body = 'The Hathigumpha inscription near Bhubaneswar records the deeds of Kharavela of Kalinga in about the first century BCE. Which one of the following does it best show?', body_hi = 'भुवनेश्वर के पास स्थित हाथीगुम्फा अभिलेख लगभग पहली सदी ई.पू. में कलिंग के खारवेल के कार्यों का वर्णन करता है। यह निम्नलिखित में से किसे सबसे अच्छी तरह दिखाता है?', explanation = 'The Prakrit inscription of Kharavela, of the Mahameghavahana (Chedi) line, records his reign year by year: campaigns against a Satavahana king and raids into Magadha, from where he says he brought back a Jina image taken away by a Nanda king, and the extension of a canal first dug in Nanda times. Kharavela was a patron of Jainism, and the caves at Udayagiri and Khandagiri were cut for Jain monks. The inscription thus shows Kalinga''s revival as an independent power after the Mauryan collapse, long before the Kushanas, who never reached Kalinga.', explanation_hi = 'महामेघवाहन (चेदि) वंश के खारवेल का प्राकृत अभिलेख उसके शासन का वर्ष-दर-वर्ष वर्णन करता है: एक सातवाहन राजा के विरुद्ध अभियान और मगध पर आक्रमण, जहाँ से वह किसी नंद राजा द्वारा ले जाई गई जिन-प्रतिमा वापस लाने की बात कहता है, और नंद काल में पहली बार खोदी गई एक नहर का विस्तार। खारवेल जैन धर्म का संरक्षक था, और उदयगिरि और खंडगिरि की गुफाएँ जैन भिक्षुओं के लिए काटी गईं। इस प्रकार अभिलेख मौर्य पतन के बाद कलिंग के एक स्वतंत्र शक्ति के रूप में पुनरुत्थान को दिखाता है, कुषाणों से बहुत पहले, जो कभी कलिंग तक नहीं पहुँचे।', concept_group_id = 'ancient-hathigumpha-inscription-kharavela', source_citation = 'Upinder Singh, A History of Ancient and Early Medieval India (Pearson)', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "Kalinga remained a province of the Mauryan empire until the end of the first century BCE", "body_hi": "कलिंग पहली सदी ई.पू. के अंत तक मौर्य साम्राज्य का प्रांत बना रहा", "isCorrect": false}, {"id": "b", "body": "Kharavela was a Buddhist ruler who opposed the spread of Jainism in Kalinga", "body_hi": "खारवेल एक बौद्ध शासक था जिसने कलिंग में जैन धर्म के प्रसार का विरोध किया", "isCorrect": false}, {"id": "c", "body": "Kalinga had again become a strong independent power within two centuries of Ashoka", "body_hi": "अशोक के दो सदी के भीतर कलिंग फिर एक शक्तिशाली स्वतंत्र शक्ति बन गया था", "isCorrect": true}, {"id": "d", "body": "Kalinga had by then been absorbed into the kingdom of the Kushanas", "body_hi": "तब तक कलिंग कुषाणों के राज्य में मिल चुका था", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ancient-hathigumpha-inscription-kharavela' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Ancient', type = 'mcq', difficulty = 'medium', body = 'Megasthenes'' ''Indica'' survives only in passages quoted by later Greek and Roman writers. Historians use it with caution mainly because:', body_hi = 'मेगस्थनीज़ की ''इंडिका'' केवल बाद के यूनानी और रोमन लेखकों द्वारा उद्धृत अंशों में बची है। इतिहासकार इसका उपयोग सावधानी से मुख्यतः इसलिए करते हैं कि:', explanation = 'Megasthenes lived at Pataliputra as the envoy of Seleucus Nicator, but his book is lost; what we have are excerpts in Strabo, Arrian and Diodorus, who may have paraphrased or chosen selectively. Some of his statements -- that Indian society had seven classes and that there were no slaves -- do not fit the Arthashastra or Ashoka''s edicts, which mention dasas. His picture of Pataliputra''s wooden walls and city boards is still valuable, but it is read alongside Indian evidence. He wrote in Greek, about the Mauryan court.', explanation_hi = 'मेगस्थनीज़ सेल्यूकस निकेटर के दूत के रूप में पाटलिपुत्र में रहा, पर उसकी पुस्तक खो गई है; हमारे पास स्ट्रैबो, एरियन और डियोडोरस के उद्धरण हैं, जिन्होंने संभवतः भावार्थ दिया या चुनकर लिया। उसके कुछ कथन, कि भारतीय समाज में सात वर्ग थे और कोई दास नहीं थे, अर्थशास्त्र या अशोक के अभिलेखों से मेल नहीं खाते, जिनमें दासों का उल्लेख है। पाटलिपुत्र की लकड़ी की दीवारों और नगर-मंडलों का उसका वर्णन अब भी मूल्यवान है, पर उसे भारतीय साक्ष्यों के साथ पढ़ा जाता है। उसने मौर्य दरबार के बारे में यूनानी में लिखा।', concept_group_id = 'ancient-megasthenes-seleucus-indica', source_citation = 'Upinder Singh, A History of Ancient and Early Medieval India (Pearson)', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "it survives only in later quotations, and claims such as ''no slavery'' clash with Indian sources", "body_hi": "यह केवल बाद के उद्धरणों में बची है, और ''दासता नहीं थी'' जैसे दावे भारतीय स्रोतों से टकराते हैं", "isCorrect": true}, {"id": "b", "body": "Megasthenes never visited India himself and wrote only from what traders at the frontier told him", "body_hi": "मेगस्थनीज़ स्वयं कभी भारत नहीं आया और केवल सीमा के व्यापारियों से सुनी बातों पर लिखा", "isCorrect": false}, {"id": "c", "body": "it describes the Gupta empire, which arose some six centuries after the court he was sent to", "body_hi": "यह गुप्त साम्राज्य का वर्णन करती है, जो उसके भेजे गए दरबार के लगभग छह सदी बाद उभरा", "isCorrect": false}, {"id": "d", "body": "it was written in Sanskrit, a language that the later Greek and Roman scholars could not read", "body_hi": "यह संस्कृत में लिखी गई थी, जिसे बाद के यूनानी और रोमन विद्वान पढ़ नहीं सकते थे", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ancient-megasthenes-seleucus-indica' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Ancient', type = 'mcq', difficulty = 'medium', body = 'The Nasadiya Sukta of the Rig Veda asks how the universe came into being and ends by wondering whether even the one who watches over it knows. It is often cited as evidence that:', body_hi = 'ऋग्वेद का नासदीय सूक्त पूछता है कि ब्रह्मांड कैसे अस्तित्व में आया, और अंत में यह संदेह करता है कि क्या उसका अधिष्ठाता भी यह जानता है। इसे प्रायः किसके प्रमाण के रूप में उद्धृत किया जाता है?', explanation = 'The hymn opens by saying there was then neither non-existence nor existence, and closes by doubting whether even the overseer in the highest heaven knows how creation began -- a striking example of open philosophical inquiry within the oldest Veda, which the Upanishads later carried further. Doubt, not certainty, is its mark. The Rig Veda as a whole remains centred on Indra, Agni and the other gods of sacrifice, and it is centuries older than Buddhism.', explanation_hi = 'सूक्त यह कहकर शुरू होता है कि तब न असत् था न सत्, और यह संदेह करते हुए समाप्त होता है कि क्या सबसे ऊँचे आकाश में बैठा अधिष्ठाता भी जानता है कि सृष्टि कैसे शुरू हुई; यह सबसे प्राचीन वेद के भीतर खुली दार्शनिक जिज्ञासा का उल्लेखनीय उदाहरण है, जिसे उपनिषदों ने आगे बढ़ाया। इसकी पहचान निश्चितता नहीं, संदेह है। समग्र ऋग्वेद इंद्र, अग्नि और यज्ञ के अन्य देवताओं पर केंद्रित रहता है, और यह बौद्ध धर्म से सदियों पुराना है।', concept_group_id = 'ancient-nasadiya-sukta', source_citation = 'R.S. Sharma, India''s Ancient Past (Oxford University Press)', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "the Rig Vedic people believed in one all-knowing creator whose word was beyond doubt", "body_hi": "ऋग्वैदिक लोग एक सर्वज्ञ सृष्टिकर्ता में विश्वास करते थे जिसके वचन पर संदेह नहीं हो सकता था", "isCorrect": false}, {"id": "b", "body": "the Vedic tradition had by then rejected the gods of sacrifice, such as Indra and Agni", "body_hi": "तब तक वैदिक परंपरा ने इंद्र और अग्नि जैसे यज्ञ के देवताओं को त्याग दिया था", "isCorrect": false}, {"id": "c", "body": "the hymn was borrowed from an early Buddhist text on the origin of the world and of life", "body_hi": "यह सूक्त संसार और जीवन की उत्पत्ति पर किसी प्रारंभिक बौद्ध ग्रंथ से लिया गया था", "isCorrect": false}, {"id": "d", "body": "speculative questioning about the first cause was part of the Vedic tradition early on", "body_hi": "आदि कारण के बारे में चिंतनशील प्रश्न पूछना प्रारंभ से ही वैदिक परंपरा का भाग था", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ancient-nasadiya-sukta' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Ancient', type = 'mcq', difficulty = 'medium', body = 'The Puranas call Mahapadma Nanda, founder of the Nanda dynasty, a ''destroyer of all Kshatriyas'' and a man of low birth. This is best read as showing that:', body_hi = 'पुराण नंद वंश के संस्थापक महापद्म नंद को ''सभी क्षत्रियों का नाशक'' और निम्न कुल का व्यक्ति कहते हैं। इसे सबसे अच्छी तरह किस रूप में पढ़ा जाता है?', explanation = 'The Brahmanical texts held that kingship belonged to the Kshatriyas, so a powerful king of humble origin was described in hostile terms; the same Puranas call him ''ekarat'', sole sovereign, a sign of how far he extended Magadha. The Nandas were an Indian dynasty, the Puranas were compiled by Brahmanical authors over a long period, and there is no evidence that Mahapadma became a Buddhist. Several later ruling houses in north India also came from outside the Kshatriya varna.', explanation_hi = 'ब्राह्मणवादी ग्रंथ मानते थे कि राजत्व क्षत्रियों का है, इसलिए साधारण कुल से उठे एक शक्तिशाली राजा का वर्णन शत्रुतापूर्ण शब्दों में किया गया; वही पुराण उसे ''एकराट्'', यानी एकमात्र सम्राट, कहते हैं, जो दिखाता है कि उसने मगध का कितना विस्तार किया। नंद एक भारतीय वंश था, पुराण ब्राह्मणवादी लेखकों ने लंबे समय में संकलित किए, और महापद्म के बौद्ध बनने का कोई प्रमाण नहीं है। उत्तर भारत के बाद के कई राजवंश भी क्षत्रिय वर्ण से बाहर के थे।', concept_group_id = 'ancient-mahapadma-nanda', source_citation = 'R.S. Sharma, India''s Ancient Past (Oxford University Press)', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "the Nandas were a foreign dynasty that had entered north-western India with the Persian armies", "body_hi": "नंद एक विदेशी वंश था जो फ़ारसी सेनाओं के साथ उत्तर-पश्चिमी भारत में आया था", "isCorrect": false}, {"id": "b", "body": "the Nandas broke the norm that kings should be Kshatriyas, and Brahmanical authors resented it", "body_hi": "नंदों ने इस मान्यता को तोड़ा कि राजा क्षत्रिय होने चाहिए, और ब्राह्मणवादी लेखकों को यह अखरा", "isCorrect": true}, {"id": "c", "body": "Mahapadma Nanda had converted to Buddhism and persecuted the Brahmanas and the Kshatriyas", "body_hi": "महापद्म नंद ने बौद्ध धर्म अपनाकर ब्राह्मणों और क्षत्रियों पर अत्याचार किया था", "isCorrect": false}, {"id": "d", "body": "the Puranas were composed by the Nandas'' own court poets to praise their rise to power", "body_hi": "पुराण नंदों के अपने दरबारी कवियों ने उनके उत्थान की प्रशंसा में रचे थे", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ancient-mahapadma-nanda' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Ancient', type = 'mcq', difficulty = 'medium', body = 'Historians check the claims of the Allahabad Prashasti, which describes the conquests of Samudragupta, against coins and other inscriptions. They do so mainly because:', body_hi = 'इतिहासकार समुद्रगुप्त की विजयों का वर्णन करने वाली प्रयाग प्रशस्ति के दावों को सिक्कों और अन्य अभिलेखों से जाँचते हैं। वे ऐसा मुख्यतः इसलिए करते हैं कि:', explanation = 'The prashasti was composed by Harishena, a court official, in ornate Sanskrit, in praise of his master: it lists kings ''uprooted'' in the north, southern kings captured and then released, and frontier peoples and distant rulers said to pay homage. Some of these claims are probably exaggerated, so historians check them against coins and other inscriptions. It was written in Samudragupta''s own time, in Gupta Brahmi, which is fully readable; it is carved on an Ashokan pillar now at Allahabad.', explanation_hi = 'प्रशस्ति दरबारी अधिकारी हरिषेण ने अलंकृत संस्कृत में अपने स्वामी की प्रशंसा में रची: इसमें उत्तर के ''उखाड़ फेंके गए'' राजा, पकड़कर फिर छोड़ दिए गए दक्षिणी राजा, और श्रद्धांजलि देने वाले बताए गए सीमांत लोग तथा दूर के शासक सूचीबद्ध हैं। इनमें से कुछ दावे संभवतः बढ़ा-चढ़ाकर कहे गए हैं, इसलिए इतिहासकार उन्हें सिक्कों और अन्य अभिलेखों से जाँचते हैं। यह समुद्रगुप्त के अपने समय में गुप्त ब्राह्मी में लिखी गई, जो पूरी तरह पढ़ी जा सकती है; यह अब इलाहाबाद में स्थित एक अशोक स्तंभ पर उत्कीर्ण है।', concept_group_id = 'ancient-allahabad-prashasti-samudragupta', source_citation = 'Upinder Singh, A History of Ancient and Early Medieval India (Pearson)', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "it was composed about three centuries after his reign, from oral traditions of the court", "body_hi": "यह उसके शासन के लगभग तीन सदी बाद दरबार की मौखिक परंपराओं से रची गई", "isCorrect": false}, {"id": "b", "body": "it is written in a script and a language that scholars have not yet fully deciphered", "body_hi": "यह ऐसी लिपि और भाषा में है जिसे विद्वान अभी पूरी तरह पढ़ नहीं पाए हैं", "isCorrect": false}, {"id": "c", "body": "it is a eulogy by his court poet, so it shows his campaigns in the most flattering light", "body_hi": "यह उसके दरबारी कवि की प्रशंसा है, इसलिए यह उसके अभियानों को सबसे प्रशंसात्मक रूप में दिखाती है", "isCorrect": true}, {"id": "d", "body": "it was inscribed by the rulers he had defeated, who played down his success", "body_hi": "इसे उसके द्वारा पराजित शासकों ने उत्कीर्ण कराया, जिन्होंने उसकी सफलता को कम करके दिखाया", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ancient-allahabad-prashasti-samudragupta' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Ancient', type = 'mcq', difficulty = 'medium', body = 'Which of the following Chinese pilgrims studied or stayed at Nalanda?
1. Fa-hien (Faxian)
2. Hiuen Tsang (Xuanzang)
3. I-tsing (Yijing)
4. Sung Yun
Select the correct answer using the code given below.', body_hi = 'निम्नलिखित में से किन चीनी यात्रियों ने नालंदा में अध्ययन किया या वहाँ रहे?
1. फ़ाह्यान
2. ह्वेनसांग
3. इत्सिंग
4. सुंग युन
नीचे दिए गए कूट का प्रयोग कर सही उत्तर चुनिए।', explanation = 'Hiuen Tsang studied at Nalanda under its head, Shilabhadra, in the 630s, and I-tsing spent about ten years there in the late seventh century, describing its discipline and daily routine. Fa-hien travelled in India in about 399-414 CE, before Nalanda grew into a great monastery, and Sung Yun, who came in about 518-22 CE, went only as far as Udyana and Gandhara in the north-west.', explanation_hi = 'ह्वेनसांग ने 630 के दशक में नालंदा के प्रमुख शीलभद्र के अधीन अध्ययन किया, और इत्सिंग सातवीं सदी के उत्तरार्ध में लगभग दस वर्ष वहाँ रहे और उसके अनुशासन तथा दिनचर्या का वर्णन किया। फ़ाह्यान लगभग 399-414 ई. में भारत में घूमे, नालंदा के एक महान विहार बनने से पहले, और लगभग 518-22 ई. में आए सुंग युन केवल उत्तर-पश्चिम में उद्यान और गांधार तक गए।', concept_group_id = 'ancient-i-tsing-nalanda', source_citation = 'Upinder Singh, A History of Ancient and Early Medieval India (Pearson)', question_data = '{"craft": "multi"}'::jsonb, options = '[{"id": "a", "body": "2 and 3 only", "body_hi": "केवल 2 और 3", "isCorrect": true}, {"id": "b", "body": "1, 2 and 3 only", "body_hi": "केवल 1, 2 और 3", "isCorrect": false}, {"id": "c", "body": "1 and 4 only", "body_hi": "केवल 1 और 4", "isCorrect": false}, {"id": "d", "body": "3 and 4 only", "body_hi": "केवल 3 और 4", "isCorrect": false}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ancient-i-tsing-nalanda' returning concept_group_id;
update public.questions set subject = 'History', topic = 'Ancient', type = 'mcq', difficulty = 'hard', body = 'At Nagarjunakonda, the Ikshvaku kings of the third and fourth centuries CE performed Vedic sacrifices, while women of the royal family built great Buddhist monasteries and stupas. This is best taken as evidence that:', body_hi = 'नागार्जुनकोंडा में तीसरी और चौथी सदी ई. के इक्ष्वाकु राजाओं ने वैदिक यज्ञ किए, जबकि राजपरिवार की स्त्रियों ने बड़े बौद्ध विहार और स्तूप बनवाए। इसे सबसे अच्छी तरह किसका प्रमाण माना जाता है?', explanation = 'The Ikshvakus ruled the lower Krishna valley from Vijayapuri after the Satavahanas. Their kings boasted of sacrifices such as the ashvamedha, while queens and princesses -- with merchants and guilds -- endowed the Mahachaitya and monasteries for several Buddhist schools. Such shared patronage within one family was common in early India and does not mean a conversion. The site was flooded by the Nagarjuna Sagar dam, and many monuments were moved to an island museum.', explanation_hi = 'सातवाहनों के बाद इक्ष्वाकुओं ने विजयपुरी से निचली कृष्णा घाटी पर शासन किया। उनके राजाओं ने अश्वमेध जैसे यज्ञों पर गर्व किया, जबकि रानियों और राजकुमारियों ने, व्यापारियों और श्रेणियों के साथ, महाचैत्य और कई बौद्ध संप्रदायों के विहारों को दान दिया। एक ही परिवार में ऐसा साझा संरक्षण प्रारंभिक भारत में आम था और इसका अर्थ धर्मांतरण नहीं है। नागार्जुन सागर बाँध से यह स्थल डूब गया, और कई स्मारक एक द्वीप-संग्रहालय में ले जाए गए।', concept_group_id = 'ancient-ikshvakus-nagarjunakonda', source_citation = 'Upinder Singh, A History of Ancient and Early Medieval India (Pearson)', question_data = '{"craft": "inference"}'::jsonb, options = '[{"id": "a", "body": "the Ikshvakus had converted to Buddhism and given up the Vedic rituals of their ancestors", "body_hi": "इक्ष्वाकुओं ने बौद्ध धर्म अपनाकर अपने पूर्वजों के वैदिक कर्मकांड छोड़ दिए थे", "isCorrect": false}, {"id": "b", "body": "women were barred from patronising Vedic ritual and so turned to Buddhism in protest", "body_hi": "स्त्रियों को वैदिक कर्मकांड को संरक्षण देने से रोका गया था, इसलिए उन्होंने विरोध में बौद्ध धर्म अपनाया", "isCorrect": false}, {"id": "c", "body": "Buddhism in the Krishna valley was a religion of the court alone, with no support from merchants", "body_hi": "कृष्णा घाटी में बौद्ध धर्म केवल दरबार का धर्म था, जिसे व्यापारियों का कोई समर्थन नहीं था", "isCorrect": false}, {"id": "d", "body": "royal households in early India often patronised more than one religious tradition at once", "body_hi": "प्रारंभिक भारत के राजपरिवार प्रायः एक साथ एक से अधिक धार्मिक परंपराओं को संरक्षण देते थे", "isCorrect": true}]'::jsonb, updated_at = now() where exam_category = 'upsc' and status in ('draft', 'published') and concept_group_id = 'ancient-ikshvakus-nagarjunakonda' returning concept_group_id;
commit;
